(window.TNQ=window.TNQ||[]).push({"terms":{"개방시스템":{"d":"조직이 환경과 자원과 정보를 주고받으며 존속한다고 보는 관점입니다.","r":["피드백"]},"피드백":{"d":"결과에 대한 정보를 되돌려 받아 이후 행동을 고치는 과정입니다.","r":["개방시스템"]},"자선적 책임":{"d":"법이나 윤리가 요구하지 않아도 사회에 자발적으로 기여하는 기업의 책임입니다.","r":[]},"소유경영자":{"d":"기업을 소유하면서 직접 경영도 맡는 경영자입니다.","r":[]},"개념적 기술":{"d":"조직 전체를 보고 복잡한 상황을 이해하며 판단하는 능력입니다.","r":[]},"원가우위 전략":{"d":"경쟁사보다 낮은 비용으로 만들어 경쟁에서 앞서려는 사업부 수준 전략입니다.","r":["차별화 전략"]},"차별화 전략":{"d":"제품이나 서비스를 남다르게 만들어 경쟁에서 앞서려는 전략입니다.","r":["원가우위 전략"]},"학습곡선":{"d":"경험이 쌓일수록 생산 단위당 비용이 줄어드는 관계를 나타낸 곡선입니다.","r":[]},"가치사슬":{"d":"원료 조달부터 판매까지 기업 활동을 가치 창출 단계로 나누어 본 틀입니다.","r":[]},"경영효율성":{"d":"투입한 자원에 비해 얼마나 많은 성과를 내는지를 가리킵니다.","r":[]},"집단의사결정":{"d":"여러 구성원이 함께 논의해 결정을 내리는 방식입니다.","r":["브레인스토밍","델파이집단기법"]},"브레인스토밍":{"d":"비판 없이 아이디어를 자유롭게 쏟아 내는 집단 아이디어 창출 기법입니다.","r":["집단의사결정"]},"델파이집단기법":{"d":"전문가들이 서로 만나지 않고 설문을 되풀이하며 의견을 모으는 기법입니다.","r":["집단의사결정"]},"과업지향적 리더":{"d":"일의 목표 달성과 과업 수행에 중심을 두는 리더입니다.","r":["관계지향적 리더"]},"관계지향적 리더":{"d":"구성원과의 관계와 인간적 유대에 중심을 두는 리더입니다.","r":["과업지향적 리더"]},"욕구단계이론":{"d":"매슬로우가 인간 욕구를 낮은 단계에서 높은 단계로 배열한 이론입니다.","r":["자아실현욕구"]},"자아실현욕구":{"d":"자기 잠재력을 발휘해 이상을 이루려는 가장 높은 단계의 욕구입니다.","r":["욕구단계이론"]},"성취동기이론":{"d":"맥클리랜드가 성취, 권력, 친교 욕구로 동기를 설명한 이론입니다.","r":[]},"기대이론":{"d":"브룸이 기대감, 수단성, 유의성으로 동기부여를 설명한 이론입니다.","r":[]},"경영통제시스템":{"d":"성과를 사전에 설정한 표준에 일치시키려는 통제 장치입니다.","r":[]},"진부화":{"d":"기술이나 유행이 바뀌어 재고의 쓸모와 가치가 떨어지는 일입니다.","r":[]},"주경로":{"d":"프로젝트에서 가장 긴 소요시간이 걸리는 활동 경로입니다.","r":[]},"안전재고":{"d":"불확실한 예상수요에 대비해 추가로 보유하는 재고입니다.","r":["재주문점"]},"재주문점":{"d":"재고가 이 수준까지 줄면 새로 주문을 내는 기준 재고량입니다.","r":["안전재고"]},"가격탄력성":{"d":"가격이 변할 때 수요량이 얼마나 민감하게 변하는지 나타내는 정도입니다.","r":[]},"진입장벽":{"d":"새로운 기업이 시장에 들어오는 것을 막는 요인입니다.","r":[]},"마케팅 믹스":{"d":"제품, 가격, 유통, 촉진 등 마케팅 수단을 조합한 것입니다.","r":[]},"요구수익률":{"d":"투자자가 투자 위험에 대한 대가로 최소한 얻으려는 수익률입니다.","r":[]}},"notes":{"0.4라는 것은 자사 사업부의 시장점유율이 그 시장에서의 경쟁 기업 중 가장 큰 점유율을 나타내는 경쟁사 시장점유율의 2/5 수준임을 의미한다":"상대적 시장점유율 0.4는 우리 점유율이 시장 최대 경쟁사 점유율의 5분의 2라는 뜻이에요.","ARR(Account Rate of Return)":"ARR은 회계상 이익으로 계산하는 수익률이라는 뜻의 영어 약어입니다.","IRR(Internal Rate of Return)":"IRR은 투자로 얻는 수익률을 뜻하며 영어 Internal Rate of Return의 약어입니다.","PBP(Pay Back Period)":"PBP는 투자한 원금을 되찾는 데 걸리는 기간이라는 뜻의 영어 약어입니다.","PI(Profitability Index)":"PI는 투자안이 수익을 얼마나 내는지 보는 지수이며 영어 Profitability Index의 약어입니다.","market-skimming":"market-skimming은 시장의 윗부분을 걷어 내듯 처음에 높은 가격을 받는다는 뜻의 영어 표현이에요.","개념적 기술은 최고경영층에게 가장 많이 요구된다":"개념적 기술은 조직 전체를 구조적으로 이해하는 능력으로, 최고경영층에 가장 많이 요구됩니다.","개방시스템 개념과 피드백 개념이 경영 발전에 중요한 영향을 미쳤다":"개방시스템은 조직이 환경과 주고받는다는 관점이고, 피드백은 결과를 되돌려 고치는 개념입니다.","개선하려는 문제의 잠재적 원인 규명에 활용된다":"특성요인도는 고치고 싶은 문제를 일으킬 수 있는 잠재 원인을 찾아내는 도구입니다.","개인이 학습과 체험을 통해 쌓은 지식으로 문서화하기 어렵다":"암묵지는 몸으로 겪으며 쌓은 지식이라 말이나 글로 옮기기 어렵습니다.","경영의 계획ㆍ조직ㆍ지휘 활동과 더불어 순환적으로 수행되어야 할 기본적인 기능이다":"통제는 계획, 조직, 지휘와 이어져 순환하며 되풀이되는 경영의 기본 기능입니다.","경영자의 역할로 대인적, 정보전달적, 의사결정적 역할을 제시하였다":"민쯔버그는 경영자 역할을 대인적, 정보전달적, 의사결정적 세 갈래로 나누었습니다.","경영통제시스템은 조직의 목표 달성을 위해 사전에 설정된 표준에 조직의 성과를 일치시키고자 하는 것이다":"경영통제시스템은 미리 정한 표준에 실제 성과를 맞추어 목표를 이루게 하려는 장치예요.","경영환경의 불확실성과 복잡성으로 인하여 집단의사결정이 개인의사결정보다 의사결 정의 질이 더 우월하다는 기본 가정하에서 이루어진다":"경영환경이 불확실하고 복잡해서 여럿이 정하는 편이 한 사람보다 결정의 질이 높다고 전제합니다.","경쟁사가 모방하기 어려운 독보적 능력이다":"핵심역량은 경쟁사가 흉내 내기 어렵다는 점에서 독보적인 능력으로 꼽힙니다.","경쟁사를 능가하는 우월적 능력이다":"핵심역량은 경쟁사보다 한 수 위라서 경쟁에서 우위를 만들어 주는 능력이에요.","경쟁우위를 갖지 못하는 사업부문을 매각한다":"경쟁에서 앞서지 못하는 사업부문은 팔아 치워서 자원을 다른 곳에 돌립니다.","고객에 대한 편익을 증대시킨다":"핵심역량은 고객이 얻는 편익을 키워 주는 기업의 능력입니다.","공정의 흐름을 묘사하는데 활용된다":"흐름도는 작업 공정이 어떤 순서로 흘러가는지 그림으로 나타내는 도구예요.","과업공유와 분권화된 의사결정을 특징으로 하며 환경 변화에 신속히 대응할 수 있다":"유기적 조직은 일을 함께 나누고 결정권을 아래로 넘기기 때문에 환경 변화에 빠르게 대응해요.","기능별 전문화, 규모의 경제 등을 추구하는 기업에 적합하다":"기능식 조직은 같은 기능끼리 모아 전문성과 규모의 경제를 살리려는 기업에 알맞습니다.","기대이론은 기대감, 수단성, 유의성을 동기부여의 요소로 제시한다":"브룸의 기대이론은 기대감, 수단성, 유의성이 곱해져 동기부여의 크기를 정한다고 봅니다.","기업 내 각 부문의 데이터를 일원화하여 관리함으로써 경영자원을 계획적이고 효율적으로 운영하도록 해 준다":"각 부문에 흩어진 데이터를 하나로 모아 관리하면 경영자원을 계획적이고 효율적으로 쓸 수 있습니다.","기업 산출물에 대한 수요의 예측력을 높일 수 있다":"전방통합을 하면 자기 제품이 얼마나 팔릴지 수요를 더 정확히 내다볼 수 있어요.","기업의 마케팅 목표 및 마케팅 믹스와의 조화를 고려하여 수립할 필요성이 있다":"가격은 기업의 마케팅 목표와 마케팅 믹스와 어긋나지 않게 정해야 합니다.","기업의 유통경로나 생산투입물의 공급원에 대한 소유나 통제를 도모하는 경영전략으로, 기업이 전방 혹은 후방으로 자사의 가치사슬 활동을 확대하고자 하는 것이다":"수직통합은 제품이 유통되는 길이나 재료 공급처를 소유하거나 통제하려는 전략이며, 가치사슬을 앞뒤로 넓히는 일입니다.","기업의 자산이 효율적으로 관리되고 있는지를 확인하는 것이다":"재무통제는 기업의 자산이 효율적으로 관리되는지를 따져 보는 통제입니다.","기업 전체와 각 부서의 활동에 대한 총체적인 흐름을 파악한다":"기업 전체와 각 부서가 어떻게 이어져 돌아가는지, 그 큰 흐름을 파악하는 것이 경영학의 시각이에요.","기업환경 변화에 탄력적으로 적응할 수 있다":"환경이 달라질 때 굳어 있지 않고 유연하게 맞춰 갈 수 있다는 점이 경영학 관점의 효용이에요.","기존 기업이 갖는 학습곡선은 새로운 경쟁자의 진입 비용을 높이는 역할을 한다":"먼저 자리 잡은 기업은 경험으로 비용이 내려가 있어서 새 경쟁자가 들어오려면 더 큰 비용을 치릅니다.","내부 물류 흐름뿐만 아니라 외부 물류 흐름의 통합에도 초점을 두고 있다":"회사 안의 물류뿐 아니라 회사 밖의 물류 흐름까지 통합하는 데 초점을 둡니다.","내부수익률이 투자안의 요구수익률보다 높은지의 여부에 따라 투자안을 평가하는 방법":"내부수익률이 요구수익률보다 높으면 그 투자안을 채택하는 평가법이에요.","대표적인 집단의사결정 기법으로 브레인스토밍, 델파이집단기법 등이 있다":"브레인스토밍과 델파이집단기법이 집단의사결정을 하는 대표 기법으로 꼽힙니다.","두 변수 간 상관관계 파악에 활용된다":"산포도는 점으로 찍어 두 변수 사이에 상관관계가 있는지 가늠하는 도구입니다.","리더와 구성원의 관계, 과업 구조, 지위 권력을 제시하였다":"상황이 리더에게 유리한지는 리더와 구성원의 관계, 과업 구조, 지위 권력 세 변수로 가립니다.","리더의 유형을 과업지향적 리더와 관계지향적 리더로 구분하였다":"상황이론은 리더를 일 중심의 과업지향적 리더와 사람 중심의 관계지향적 리더로 가릅니다.","보유자원의 특이성이 클수록 경쟁우위를 획득할 가능성이 크다":"자원기반관점에서는 남이 갖기 힘든 특이한 자원일수록 경쟁에서 앞설 가능성이 커진다고 봅니다.","보험료, 도난, 파손, 진부화 등과 관련된 비용":"재고유지비용은 보험료, 도난, 파손, 진부화처럼 재고를 쌓아 두기 때문에 생기는 비용입니다.","불필요한 인원을 감축함으로써 경영효율성을 높인다":"필요 없는 인원을 줄이면 같은 일을 더 적은 인력으로 하게 되어 경영효율성이 높아집니다.","불확실한 예상수요에 대비하기 위한 재고를 안전재고라고 한다":"안전재고는 예상한 수요가 틀릴 때를 대비해 여유로 쌓아 두는 재고입니다.","사람의 행동과 의사결정에 지침을 주는 본능, 지각, 아이디어, 규칙과 절차 등의 결합을 의미하며 개인의 자산이자 기업의 자원으로써 부가가치 창출에서 차지하는 역할이 커지 고 있다":"지식은 본능, 지각, 아이디어, 규칙과 절차가 결합된 것이며 부가가치를 만드는 역할이 점점 커지고 있어요.","상황이 리더에게 매우 호의적이면 과업지향적 리더가 더 좋은 성과를 보인다":"상황이 리더에게 아주 호의적일 때는 일 중심 리더가 더 나은 성과를 냅니다.","생산설비 가동준비에 소요되는 비용":"가동준비비용은 생산설비를 돌리기 전에 준비하는 데 드는 비용입니다.","생산투입물에 대한 공급안정성을 높이고자 하는 경우 채택하게 된다":"후방통합은 재료와 부품을 안정적으로 공급받고 싶을 때 선택하는 전략입니다.","선진 프로세스를 내장하고 있는 패키지 도입 시 기업의 업무처리 방식을 최적화하는 데 도움이 될 수 있다":"패키지에 담긴 선진 프로세스를 도입하면 기업의 업무처리 방식을 최적화하는 데 도움이 될 수 있어요.","성취동기이론은 성취욕구, 권력욕구, 친교욕구를 제시하여 동기부여를 설명한다":"맥클리랜드의 성취동기이론은 성취, 권력, 친교 세 욕구가 동기를 일으킨다고 설명합니다.","소비자들의 본원적 수요를 자극하고자 하는 경우":"상대적 저가격전략은 소비자의 본원적 수요를 일으키려는 경우에 알맞은 가격 전략입니다.","소수의 구성원이 집단의사결정 과정을 지배하여 구성원들의 자유로운 의사표현이 방해를 받을 수 있다":"몇 사람이 토론을 휘어잡으면 나머지가 자유롭게 말하지 못한다는 약점이 있어요.","소유경영자에 비해 단기적 기업이익을 추구하는 성향을 보인다":"전문경영자는 소유경영자보다 당장의 이익에 치우치기 쉽다는 지적이 있습니다.","수량이 많고 부피가 작은 저가품 관리에 많이 활용된다":"투빈시스템은 통을 두 개 두고 한쪽이 비면 주문하는 방식이며, 수량이 많고 작고 싼 물건에 알맞습니다.","수요의 가격탄력성이 높지 않을 경우":"상대적 고가격전략은 값이 올라도 수요가 크게 줄지 않는, 가격탄력성이 낮은 경우에 씁니다.","수주처리에서 출하 및 회계처리까지 일련의 업무통합으로 고객 요구에 신속하고 정확 하게 대응할 수 있다":"주문을 받은 뒤 출하와 회계까지 업무가 하나로 이어져서 고객 요구에 빠르고 정확하게 대응합니다.","언어, 문자, 숫자의 형태로 존재하는 지식을 말한다":"형식지는 언어, 문자, 숫자로 겉에 드러나 있어서 문서로 전달할 수 있는 지식이에요.","영리를 추구하는 조직뿐만 아니라 비영리조직에도 경영의 개념이 필요하다":"이익을 내지 않는 단체도 한정된 자원으로 목표를 이뤄야 하므로 경영이 필요합니다.","욕구단계이론에서 최상위 욕구는 자아실현욕구이다":"매슬로우의 욕구단계이론에서 가장 높은 단계의 욕구는 자아실현욕구예요.","원가우위 전략, 차별화 전략 등":"원가우위 전략은 비용을 낮춰 이기는 것이고, 차별화 전략은 남다른 특징으로 이기는 것이에요.","유휴생산시설을 줄임으로써 비용절감을 꾀한다":"놀고 있는 생산시설을 줄이면 유지에 드는 돈이 줄어 비용이 절감됩니다.","의사결정의 결과에 대한 구성원의 수용가능성 증진":"구성원이 결정 과정에 참여했기 때문에 결과를 받아들이고 따를 가능성이 높아집니다.","인터넷을 비롯한 정보통신기술의 진전을 들 수 있다":"인터넷 같은 정보통신기술이 발달하면서 공급사슬관리가 널리 퍼졌습니다.","자선적 책임은 경제적, 법적, 윤리적 책임과 관계없이 수행된다":"자선적 책임은 경제적, 법적, 윤리적 책임과 따로 떨어져 자발적으로 하는 사회 공헌입니다.","재고수준이 재주문점에 도달하면 일정량만큼 주문한다":"EOQ모형에서는 재고가 재주문점까지 줄면 미리 정한 일정량을 주문합니다.","재고품목의 구매비용이나 생산비용":"품목비용은 재고로 가진 품목을 사거나 만드는 데 들어간 돈이에요.","전체적인 입장에서 통합ㆍ조정을 중시한다":"경영학은 부분이 아니라 전체의 시각에서 여러 활동을 하나로 묶고 맞추는 데 무게를 둡니다.","정보공유를 토대로 공급업체, 제조업체, 유통업체 및 소비자를 유기적으로 연결하여 통합적으로 관리하는 시스템을 말한다":"공급사슬관리는 정보를 나눠 공급업체부터 소비자까지 한 덩어리로 묶어 관리하는 시스템입니다.","조직개편을 통해 조직을 단순화하고 군살을 뺀다":"조직개편은 겹치는 단계를 줄여 구조를 단순하게 만들고 군더더기를 덜어 내는 일이에요.","조직문화, 고객과의 신뢰 등과 같이 인과관계의 모호성이 큰 자원일수록 모방이 어렵다":"조직문화나 신뢰는 무엇이 성과를 낳았는지 원인이 불분명해서 경쟁사가 따라 하기 어렵습니다.","조직의 모든 자원을 계획, 조직, 지휘, 통제 하는 과정을 말한다":"경영은 자원에 대해 계획을 세우고 조직하고 지휘하고 통제하는 네 가지 과정으로 이루어집니다.","조직의 목표를 성공적으로 달성하기 위해":"경영의 목적은 조직이 목표를 이루는 것이며, 그 수단은 조직이 가진 자원을 다루는 일입니다.","조직의 상층부에 속한 최고 의사결정자뿐만 아니라 조직의 모든 구성원을 대상으로 한다":"경영은 최고 의사결정자만의 일이 아니라 조직 구성원 모두와 관련된 활동이에요.","조직의 특정 과업 해결을 위해 조직의 일상적 업무 수행 기구와는 별도로 구성된 전문가 혹은 업무관계자들의 활동조직이다":"위원회 조직은 특정 과업을 풀려고 일상 업무 조직과 따로 전문가나 관계자를 모아 꾸린 조직이에요.","주경로의 소요시간이 프로젝트의 최단완료시간이 된다":"주경로는 프로젝트에서 가장 오래 걸리는 경로여서 그 소요시간이 곧 최단완료시간이 됩니다.","중간경영층이 많이 사용 하는 통제기법이다":"예산통제는 중간경영층이 즐겨 쓰는 통제기법이에요.","진입장벽이 높아 경쟁자의 시장 진입이 어려운 경우":"스키밍 가격 전략은 진입장벽이 높아 경쟁자가 들어오기 어려운 경우에 쓸 수 있습니다.","초기 결정이 잘못된 것을 알고도 그 결정을 고수하기 위해 인적ㆍ물적 자원을 지속적으로 제공하는 것을 말한다":"초기 결정 고수는 틀렸음을 알면서도 그 결정을 밀고 가려고 사람과 물자를 계속 쏟아붓는 현상입니다.","투자안의 현금흐름을 고려하여 투자안을 평가 하는 방법":"수익성지수법은 투자안이 만들어 내는 현금흐름을 반영해서 평가하는 방법이에요.","투자원금을 회수하는 기간만을 고려하여 투자 안을 평가하는 방법":"회수기간법은 원금을 되찾는 기간만 따지고 그 뒤의 현금흐름은 보지 않는 평가법이에요.","품질특성의 발생 빈도를 기록하는데 활용된다":"체크시트는 품질특성이 몇 번 나타났는지 빈도를 적어 두는 도구예요.","한 명의 부하가 두 명의 상사에게 보고하며, 이중적 명령계통으로 인해 중첩되는 부문 간 갈등이 야기될 수 있다":"매트릭스 조직은 한 부하가 상사 둘에게 보고하는 이중 명령계통이라 부문 사이에 충돌이 생길 수 있습니다.","회계처리방법의 선택에 따라 투자 안의 평가결과가 달라질 수 있다":"회계적이익률법은 어떤 회계처리방법을 택하느냐에 따라 같은 투자안도 결과가 달라지는 약점이 있어요."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
